package assistant

import (
	"jasmine/internal/module/workout"
	"fmt"
	"strings"
)

// ProgressionSignal is computed from performed sets, never generated by a model.
type ProgressionSignal struct {
	TrackingType      string   `json:"tracking_type"`
	LastReps          *int     `json:"last_reps,omitempty"`
	LastWeightKg      *float64 `json:"last_weight_kg,omitempty"`
	LastBaseWeightKg  *float64 `json:"last_base_weight_kg,omitempty"`
	LastAddedWeightKg *float64 `json:"last_added_weight_kg,omitempty"`
	LastAssistanceKg  *float64 `json:"last_assistance_kg,omitempty"`
	LastTimeMin       *float64 `json:"last_time_min,omitempty"`
	LastDistanceKm    *float64 `json:"last_distance_km,omitempty"`
	Difficulty        string   `json:"difficulty,omitempty"`
	Recommendation    string   `json:"recommendation"`
}

func ComputeProgression(c CandidateExercise, history []workout.Workout) *ProgressionSignal {
	for _, w := range history {
		for _, ex := range w.Exercises {
			if ex.ExerciseID != c.ExerciseID || len(ex.Sets) == 0 {
				continue
			}
			set := ex.Sets[len(ex.Sets)-1]
			p := &ProgressionSignal{TrackingType: c.TrackingType, LastReps: set.Reps, LastWeightKg: set.WeightKg, LastBaseWeightKg: set.BaseWeightKg, LastAddedWeightKg: set.AddedWeightKg, LastAssistanceKg: set.AssistanceKg, LastTimeMin: set.TimeMin, LastDistanceKm: set.DistanceKm, Difficulty: set.Difficulty}
			if p.Difficulty == "" {
				low := strings.ToLower(c.RecentFeedback)
				if strings.Contains(low, "easy") || strings.Contains(low, "легко") {
					p.Difficulty = "easy"
				}
				if strings.Contains(low, "hard") || strings.Contains(low, "тяж") {
					p.Difficulty = "hard"
				}
			}
			switch c.TrackingType {
			case "bodyweight_assisted":
				if set.AssistanceKg != nil {
					if p.Difficulty == "easy" {
						p.Recommendation = "reduce_assistance_small_step"
					} else if p.Difficulty == "hard" || p.Difficulty == "very_hard" {
						p.Recommendation = "maintain_or_increase_assistance"
					} else {
						p.Recommendation = "maintain_assistance"
					}
				}
			case "machine_weight":
				if set.BaseWeightKg != nil || set.AddedWeightKg != nil {
					if p.Difficulty == "easy" {
						p.Recommendation = "increase_added_weight_small_step"
					} else {
						p.Recommendation = "maintain_machine_components"
					}
				}
			case "time_distance":
				p.Recommendation = "maintain_time_distance_baseline"
			default:
				if set.WeightKg != nil {
					if p.Difficulty == "easy" {
						p.Recommendation = "increase_load_small_step"
					} else if p.Difficulty == "hard" || p.Difficulty == "very_hard" {
						p.Recommendation = "maintain_or_reduce_load"
					} else {
						p.Recommendation = "maintain_load"
					}
				}
			}
			return p
		}
	}
	return nil
}
func ApplyProgression(p *WorkoutProposalDraft, candidates []CandidateExercise) {
	byID := map[string]CandidateExercise{}
	for _, c := range candidates {
		byID[c.ExerciseID] = c
	}
	var notes []string
	for i := range p.Exercises {
		ex := &p.Exercises[i]
		cand, ok := byID[ex.ExerciseID]
		if !ok || cand.Progression == nil {
			continue
		}
		sig := cand.Progression
		for j := range ex.Sets {
			s := &ex.Sets[j]
			switch sig.TrackingType {
			case "bodyweight_assisted":
				if sig.LastAssistanceKg != nil {
					v := *sig.LastAssistanceKg
					if sig.Recommendation == "reduce_assistance_small_step" && v >= 2.5 {
						v -= 2.5
					}
					if sig.Recommendation == "maintain_or_increase_assistance" && s.AssistanceKg != nil && *s.AssistanceKg > v {
						v = *s.AssistanceKg
					}
					s.AssistanceKg = &v
					s.WeightKg = nil
				}
			case "machine_weight":
				if sig.LastBaseWeightKg != nil {
					v := *sig.LastBaseWeightKg
					s.BaseWeightKg = &v
				}
				if sig.LastAddedWeightKg != nil {
					v := *sig.LastAddedWeightKg
					if sig.Recommendation == "increase_added_weight_small_step" {
						v += 2.5
					}
					s.AddedWeightKg = &v
				}
				s.WeightKg = nil
			case "time_distance":
				if sig.LastTimeMin != nil {
					v := int(*sig.LastTimeMin)
					if v > 0 {
						s.TimeMin = &v
					}
				}
				if sig.LastDistanceKm != nil {
					v := *sig.LastDistanceKm
					s.DistanceKm = &v
				}
			default:
				if sig.LastWeightKg != nil {
					v := *sig.LastWeightKg
					if sig.Recommendation == "increase_load_small_step" {
						v += 4
						if v > 1000 {
							v = 1000
						}
					}
					if sig.Recommendation == "maintain_or_reduce_load" && s.WeightKg != nil && *s.WeightKg < v {
						v = *s.WeightKg
					}
					s.WeightKg = &v
				}
			}
		}
		if sig.Recommendation != "" {
			notes = append(notes, fmt.Sprintf("%s:%s", ex.ExerciseName, sig.Recommendation))
		}
	}
	if len(notes) > 0 {
		p.AdaptationNote = strings.Join(notes, "; ")
	}
}
